from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid divider is the uniform column nearest the center.
    uniform = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    sep = min(uniform, key=lambda c: abs(c - (w - 1) / 2))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    n = min(len(left[0]), len(right[0]))

    def background(panel):
        return Counter(v for row in panel for v in row).most_common(1)[0][0]

    lb, rb = background(left), background(right)

    if lb == rb:
        return [
            [2 if left[r][c] != lb or right[r][c] != rb else 3
             for c in range(n)]
            for r in range(h)
        ]

    # Transfer the pattern whose color matches the other half's background,
    # retaining it only where the other half is at its background.
    if rb != lb and any(v == rb for row in left for v in row):
        return [
            [3 if left[r][c] == rb and right[r][c] == rb else rb
             for c in range(n)]
            for r in range(h)
        ]
    if any(v == lb for row in right for v in row):
        return [
            [3 if right[r][c] == lb and left[r][c] == lb else lb
             for c in range(n)]
            for r in range(h)
        ]

    return [[lb for _ in range(n)] for _ in range(h)]
